// GENERATED by scripts/build-cloud-sync.js from lib/ebayCondition.js. Do not edit.
// Item condition, read from eBay. eBay is the source of truth for every eBay-listed item.
//
// Pure functions only, so the same rules run on this computer and in the cloud sync
// (scripts/build-cloud-sync.js copies this file to supabase/functions/ebay-sync/condition.mjs).
//
// Where the condition comes from:
//   - Trading API GetItem: ConditionDisplayName (the words the buyer sees), ConditionID, and for
//     trading cards ConditionDescriptors (the card condition of an ungraded card).
//   - Inventory API: a condition word such as NEW or USED_EXCELLENT.
// GetMyeBaySelling (the live list) never includes it, which is why the old import saved "Unknown".
// An unknown condition is stored as nothing, never guessed.

const CONDITION_BY_ID = {
  1000: "New",
  1500: "New other (see details)",
  1750: "New with defects",
  2000: "Certified - Refurbished",
  2010: "Excellent - Refurbished",
  2020: "Very Good - Refurbished",
  2030: "Good - Refurbished",
  2500: "Seller refurbished",
  2750: "Like New",
  2990: "Pre-owned - Excellent",
  3000: "Used",
  3010: "Pre-owned - Fair",
  4000: "Very Good",
  5000: "Good",
  6000: "Acceptable",
  7000: "For parts or not working",
};

const CONDITION_BY_WORD = {
  NEW: "New",
  LIKE_NEW: "Like New",
  NEW_OTHER: "New other",
  NEW_WITH_DEFECTS: "New with defects",
  CERTIFIED_REFURBISHED: "Certified - Refurbished",
  EXCELLENT_REFURBISHED: "Excellent - Refurbished",
  VERY_GOOD_REFURBISHED: "Very Good - Refurbished",
  GOOD_REFURBISHED: "Good - Refurbished",
  SELLER_REFURBISHED: "Seller refurbished",
  REFURBISHED: "Refurbished",
  USED: "Used",
  VERY_GOOD: "Very Good",
  USED_EXCELLENT: "Used - Excellent",
  USED_VERY_GOOD: "Used - Very good",
  USED_GOOD: "Used - Good",
  USED_ACCEPTABLE: "Used - Acceptable",
  PRE_OWNED_EXCELLENT: "Pre-owned - Excellent",
  PRE_OWNED_FAIR: "Pre-owned - Fair",
  FOR_PARTS_OR_NOT_WORKING: "For parts or not working",
};

// Trading cards: descriptor 40001 is "Card Condition" on an ungraded card.
const CARD_CONDITION_DESCRIPTOR = "40001";
const CARD_CONDITION_BY_VALUE = {
  400010: "Near mint or better",
  400011: "Excellent",
  400012: "Very good",
  400013: "Poor",
};

const DAY_MS = 24 * 60 * 60 * 1000;
const DEFAULT_SLOTS = 96; // one slot per 15-minute sync run, so each listing is re-checked once a day
const DEFAULT_MAX_CHECKS = 25; // GetItem calls per run, well inside eBay's daily allowance

const clean = (value) => {
  const text = String(value ?? "").replace(/\s+/g, " ").trim();
  return text || null;
};

/** The standard eBay name for a condition number, or null. */
function conditionFromId(id) {
  return CONDITION_BY_ID[Number(id)] || null;
}

/** An Inventory API condition word (NEW, USED_EXCELLENT, ...) as a readable name, or null. */
function conditionFromInventoryEnum(word) {
  return CONDITION_BY_WORD[String(word ?? "").trim().toUpperCase()] || null;
}

function cardCondition(item) {
  const list = [].concat(item?.ConditionDescriptors?.ConditionDescriptor || []);
  const card = list.find((d) => String(d?.Name) === CARD_CONDITION_DESCRIPTOR);
  return card ? CARD_CONDITION_BY_VALUE[Number(card.Value)] || null : null;
}

/** The condition of one GetItem Item, as the buyer sees it on eBay. Null when eBay gives none. */
function conditionFromTradingItem(item) {
  if (!item || typeof item !== "object") return null;
  const name = clean(item.ConditionDisplayName) || conditionFromId(item.ConditionID);
  if (!name) return null;
  const card = cardCondition(item);
  return card && /^ungraded$/i.test(name) ? `${name} - ${card}` : name;
}

/** True when no real condition is saved (empty, or the old "Unknown" placeholder). */
function isMissingCondition(condition) {
  const text = clean(condition);
  return !text || text.toLowerCase() === "unknown";
}

/**
 * Which products this sync run should ask eBay about: every live listing with no condition saved,
 * then the listings whose turn it is today (each one comes up once a day), at most `max`.
 * @param {{ id: string, ebay_listing_id: string|null, condition: string|null }[]} products
 * @param {Set<string>|Map<string, any>} live  eBay listing ids that are live right now
 */
function pickConditionChecks(products, live, { now = Date.now(), slots = DEFAULT_SLOTS, max = DEFAULT_MAX_CHECKS } = {}) {
  const slot = Math.floor(now / (DAY_MS / slots)) % slots;
  const onEbay = products.filter((p) => p.ebay_listing_id && live.has(String(p.ebay_listing_id)));
  const missing = onEbay.filter((p) => isMissingCondition(p.condition));
  const due = onEbay.filter((p) => !isMissingCondition(p.condition) && Number(String(p.ebay_listing_id).replace(/\D/g, "") || 0) % slots === slot);
  return [...missing, ...due].slice(0, max);
}

export { conditionFromTradingItem, conditionFromId, conditionFromInventoryEnum, isMissingCondition, pickConditionChecks };